def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    # Recolor monochromatic full rows and columns, preserving their common marker color.
    lines=[]
    for r,row in enumerate(g):
        if len(set(row))==1: lines.append(([(r,c) for c in range(w)],row[0]))
    for c in range(w):
        vals=[g[r][c] for r in range(h)]
        if len(set(vals))==1: lines.append(([(r,c) for r in range(h)],vals[0]))
    for cells,color in lines:
        for r,c in cells: g[r][c]=2
    return g
